"""Weekly timesheet rows built from a list of shifts."""

from typing import Dict, Iterable, List, Tuple

from hourglass.errors import ProjectError
from hourglass.models import Shift

Tally = Dict[str, Tuple[int, int]]

def _tally(shifts: Iterable[Shift]) -> Tally:
    """Shift count and total minutes for each worker."""
    totals = {}
    for shift in shifts:
        if not shift.worker.strip():
            raise ProjectError("shift has no worker name")
        count, mins = totals.get(shift.worker, (0, 0))
        mins += shift.span.minutes
        totals[shift.worker] = (count + 1, mins)
    return totals

def _busiest_first(item):
    name, (count, mins) = item
    return (-mins, -count, name)

def timesheet_lines(shifts: Iterable[Shift]) -> List[str]:
    """One line per worker, busiest first."""
    totals = _tally(shifts)
    if not totals:
        raise ProjectError("no shifts given")
    ranked = sorted(totals.items(), key=_busiest_first)
    return [
        f"{name}: {count} shifts, {mins / 60:.1f} hours"
        for name, (count, mins) in ranked
    ]

