import unittest

from hourglass.errors import ProjectError
from hourglass.models import Shift, Span
from hourglass.timesheet import timesheet_lines

def make_shift(worker, start, end):
    return Shift(worker, "mon", Span(start * 60, end * 60))

class TimesheetTests(unittest.TestCase):
    def test_busiest_first_with_one_decimal(self):
        shifts = [
            make_shift("Bea", 9, 10),
            make_shift("Ana", 9, 12),
            make_shift("Ana", 13, 15),
            make_shift("Bea", 11, 12),
        ]
        self.assertEqual(
            timesheet_lines(shifts),
            [
                "Ana: 2 shifts, 5.0 hours",
                "Bea: 2 shifts, 2.0 hours",
            ],
        )

    def test_rounds_to_one_decimal(self):
        shift = Shift("Cy", "tue", Span(540, 580))
        self.assertEqual(
            timesheet_lines([shift]),
            ["Cy: 1 shifts, 0.7 hours"],
        )

    def test_empty_list_raises(self):
        with self.assertRaises(ProjectError):
            timesheet_lines([])

    def test_blank_worker_raises(self):
        with self.assertRaises(ProjectError):
            timesheet_lines([make_shift("  ", 9, 10)])
